const filtered=coopSource.filter(r=>(String(r.sn)+" "+r.name).toLowerCase().includes(searchMember.toLowerCase()));
const moneyCell=value=>Number(value||0).toLocaleString("en-NG");
const exportSheet=()=>{const rows=[["S/N","Member Name","April 2026 Savings Balance (NGN)","May 2026 Savings Collection (NGN)","May 2026 Savings Withdrawal (NGN)","Savings Balance (NGN)","April 2026 Loan Balance (NGN)","May 2026 Loan Collection (NGN)","May 2026 Loan Paid (NGN)"],...filtered.map(r=>[r.sn,r.name,r.aprSav,r.mayColl,r.mayWT,r.savingsBal,r.aprLoan,r.mayLoanColl,r.mayLoanPaid])];const cell=v=>{const s=String(v??"");return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s};const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([rows.map(row=>row.map(cell).join(",")).join("\r\n")],{type:"text/csv;charset=utf-8"}));a.download="pwfb-cooperative-sheet-8-june-2026.csv";a.click();};
return <div className="coop-ledger-page"><div className="coop-ledger-heading"><div><p className="coop-eyebrow">SHEET 8 · JUNE 2026</p><h2>PWFB Cooperative — Member Savings &amp; Loan Summary</h2><p>Source figures are displayed as supplied, without corrections or recalculation.</p></div><button type="button" className="coop-export-button" onClick={exportSheet}>Export Sheet 8 CSV</button></div><div className="coop-summary-grid"><div><span>Source rows</span><strong>{coopSource.length}</strong><small>Includes the supplied blank row</small></div><div><span>Named members</span><strong>{coopSource.filter(r=>!r.name.startsWith("-")).length}</strong><small>Names as supplied</small></div><div><span>Reporting sheet</span><strong>Sheet 8</strong><small>June 2026</small></div><div><span>Source amounts</span><strong>Unchanged</strong><small>No recalculation</small></div></div><div className="coop-table-toolbar"><label className="coop-search">Search member<input value={searchMember} onChange={e=>setSearchMember(e.target.value)} placeholder="Serial number or member name"/></label><span>{filtered.length} of {coopSource.length} rows</span></div><div className="table-wrap"><table className="coop-sheet8-table"><thead><tr><th rowSpan="2">S/N</th><th rowSpan="2">Member name</th><th>April 2026</th><th>May 2026</th><th>May 2026</th><th>May 2026</th><th>April 2026</th><th>May 2026</th><th>May 2026</th></tr><tr><th>Savings balance (₦)</th><th>S. collection (₦)</th><th>Savings withdrawal (₦)</th><th>Savings balance (₦)</th><th>Loan balance (₦)</th><th>Loan collection (₦)</th><th>Loan paid (₦)</th></tr></thead><tbody>{filtered.map(r=><tr key={r.sn}><td>{r.sn}</td><td className="text-left">{r.name}</td><td>{moneyCell(r.aprSav)}</td><td>{moneyCell(r.mayColl)}</td><td>{moneyCell(r.mayWT)}</td><td>{moneyCell(r.savingsBal)}</td><td>{moneyCell(r.aprLoan)}</td><td>{moneyCell(r.mayLoanColl)}</td><td>{moneyCell(r.mayLoanPaid)}</td></tr>)}</tbody></table></div><p className="coop-storage-note">Read-only June 2026 source snapshot. Export a CSV copy when needed. This page does not change payroll, transport schedules, or the existing server records.</p></div>
